import React from "react";
import { useNavigate } from "react-router-dom";
import { employeesData } from "./data";

const EmployeeList = () => {
  const navigate = useNavigate();

  return (
    <div>
      <h1>Employee List</h1>
      <button onClick={() => navigate("/salary-chart")}>View Salary Chart</button>

      <table border="1" cellPadding="8" style={{ marginTop: "20px" }}>
        <thead>
          <tr>
            <th>Name</th>
            <th>Role</th>
            <th>Location</th>
            <th>ID</th>
            <th>Date</th>
            <th>Salary</th>
          </tr>
        </thead>
        <tbody>
          {employeesData.map((emp, idx) => (
            <tr key={idx}>
              <td>{emp.name}</td>
              <td>{emp.role}</td>
              <td>{emp.location}</td>
              <td>{emp.id}</td>
              <td>{emp.date}</td>
              <td>{emp.salary}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default EmployeeList;
